import{_ as o,o as t,c as r,ae as s}from"./chunks/framework.vXWZTEWX.js";const m=JSON.parse('{"title":"The TenderCheck AI Clean Architecture Map","description":"","frontmatter":{},"headers":[],"relativePath":"CLEAN_ARCHITECTURE_MAP.md","filePath":"CLEAN_ARCHITECTURE_MAP.md"}'),i={name:"CLEAN_ARCHITECTURE_MAP.md"};function n(a,e,l,c,d,u){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="the-tendercheck-ai-clean-architecture-map" tabindex="-1">The TenderCheck AI Clean Architecture Map <a class="header-anchor" href="#the-tendercheck-ai-clean-architecture-map" aria-label="Permalink to &quot;The TenderCheck AI Clean Architecture Map&quot;">​</a></h1><p>Welcome to the engine room! 🏗️ This document maps out exactly how our application is structured, folder by folder, and how the data flows through it.</p><hr><h2 id="🏗️-the-big-picture-4-layers" tabindex="-1">🏗️ The Big Picture: 4 Layers <a class="header-anchor" href="#🏗️-the-big-picture-4-layers" aria-label="Permalink to &quot;🏗️ The Big Picture: 4 Layers&quot;">​</a></h2><p>Think of the app as a circle with layers. <strong>The Golden Rule</strong>: Dependencies only point <strong>INWARD</strong>. The inner layers (Business Logic) know <em>nothing</em> about the outer layers (Database, Web).</p><h3 id="_1-🟢-domain-layer-src-domain" tabindex="-1">1. 🟢 Domain Layer (<code>src/domain</code>) <a class="header-anchor" href="#_1-🟢-domain-layer-src-domain" aria-label="Permalink to &quot;1. 🟢 Domain Layer (`src/domain`)&quot;">​</a></h3><p><em>The &quot;Heart&quot;. Pure business logic. Zero dependencies on libraries.</em></p><ul><li><strong>Role</strong>: Defines <strong>WHAT</strong> the business is (Entities) and <strong>WHAT</strong> we can do (Interfaces).</li><li><strong>Folders</strong>: <ul><li><strong><code>/entities</code></strong>: The core objects. <ul><li><em>Example</em>: <code>Tender</code> (has <code>id</code>, <code>title</code>, <code>deadline</code>). It validates itself (e.g., &quot;deadline cannot be in the past&quot;).</li></ul></li><li><strong><code>/repositories</code> (Interfaces)</strong>: The Contracts. <ul><li><em>Example</em>: <code>ITenderRepository</code>. It says, &quot;Whoever implements me MUST have a <code>save()</code> method.&quot; It does NOT know about SQL.</li></ul></li><li><strong><code>/errors</code></strong>: Custom business errors. <ul><li><em>Example</em>: <code>TenderNotFoundError</code>, <code>InvalidBudgetElementError</code>.</li></ul></li><li><strong><code>/value-objects</code></strong>: Small, immutable objects with validation. <ul><li><em>Example</em>: <code>Money</code> (combines amount + currency), <code>Email</code> (validates format). <em>Currently empty as we use simple types, but ready for growth.</em></li></ul></li></ul></li></ul><h3 id="_2-🟡-application-layer-src-application" tabindex="-1">2. 🟡 Application Layer (<code>src/application</code>) <a class="header-anchor" href="#_2-🟡-application-layer-src-application" aria-label="Permalink to &quot;2. 🟡 Application Layer (`src/application`)&quot;">​</a></h3><p><em>The &quot;Brain&quot;. Orchestrates the work.</em></p><ul><li><strong>Role</strong>: Handles specific user actions (Use Cases). It connects the core entities with the outside world tools.</li><li><strong>Folders</strong>: <ul><li><strong><code>/use-cases</code></strong>: The Verbs. One file per action. <ul><li><em>Example</em>: <code>CreateTenderUseCase</code>.</li><li><em>Logic</em>: <ol><li>Take input (title, budget).</li><li>Create a <code>Tender</code> entity.</li><li>Call <code>tenderRepository.save()</code>.</li><li>Return success.</li></ol></li></ul></li><li><strong><code>/services</code></strong>: Logic that involves multiple entities or doesn&#39;t fit a single use case. <ul><li><em>Example</em>: <code>NotificationService</code> (send email when X happens).</li></ul></li></ul></li></ul><h3 id="_3-🔵-infrastructure-layer-src-infrastructure" tabindex="-1">3. 🔵 Infrastructure Layer (<code>src/infrastructure</code>) <a class="header-anchor" href="#_3-🔵-infrastructure-layer-src-infrastructure" aria-label="Permalink to &quot;3. 🔵 Infrastructure Layer (`src/infrastructure`)&quot;">​</a></h3><p><em>The &quot;Tools&quot;. The implementations that do the dirty work.</em></p><ul><li><strong>Role</strong>: Implements the interfaces defined in Domain. Connects to Databases, APIs, File Systems.</li><li><strong>Folders</strong>: <ul><li><strong><code>/repositories</code> (Implementations)</strong>: The actual code for the database. <ul><li><em>Example</em>: <code>TursoTenderRepository</code>. Implements <code>ITenderRepository</code>. It creates the SQL query <code>INSERT INTO tenders...</code> using the Turso client.</li></ul></li><li><strong><code>/config</code></strong>: Configuration and Environment variables (Environment variables, Secrets).</li><li><strong><code>/utils</code></strong>: Technical helpers not related to business. <ul><li><em>Example</em>: <code>safeExecute</code> (try-catch wrapper).</li></ul></li><li><strong><code>/services</code></strong>: Implementation of technical services. <ul><li><em>Example</em>: <code>SendGridEmailService</code> (implements the <code>EmailService</code> interface).</li></ul></li></ul></li></ul><h3 id="_4-🔴-presentation-layer-src-presentation" tabindex="-1">4. 🔴 Presentation Layer (<code>src/presentation</code>) <a class="header-anchor" href="#_4-🔴-presentation-layer-src-presentation" aria-label="Permalink to &quot;4. 🔴 Presentation Layer (`src/presentation`)&quot;">​</a></h3><p><em>The &quot;Face&quot;. Talks to the outer world (HTTP/Web).</em></p><ul><li><strong>Role</strong>: Accepts requests, parses data, calls the Application layer, and sends responses.</li><li><strong>Folders</strong>: <ul><li><strong><code>/controllers</code></strong>: The entry points. <ul><li><em>Example</em>: <code>TenderController</code>.</li><li><em>Logic</em>: <ol><li>Receive <code>POST /tenders</code> request.</li><li>Extract <code>req.body.title</code>.</li><li>Call <code>CreateTenderUseCase.execute()</code>.</li><li>Send <code>201 Created</code> response.</li></ol></li></ul></li><li><strong><code>/routes</code></strong>: URL definitions. <ul><li><em>Example</em>: <code>tenderRoutes.ts</code> maps <code>POST /</code> to <code>TenderController.create</code>.</li></ul></li><li><strong><code>/middleware</code></strong>: Interceptors (Auth, Logging, Validation). <ul><li><em>Example</em>: <code>authMiddleware</code> checks for a valid token before the controller runs.</li></ul></li></ul></li></ul><hr><h2 id="🔄-how-they-connect-the-life-of-a-request" tabindex="-1">🔄 How They Connect (The Life of a Request) <a class="header-anchor" href="#🔄-how-they-connect-the-life-of-a-request" aria-label="Permalink to &quot;🔄 How They Connect (The Life of a Request)&quot;">​</a></h2><p>Let&#39;s trace a User searching for a Tender:</p><ol><li><strong>Request</strong>: User clicks &quot;Search&quot; -&gt; Browser sends <code>GET /tenders?q=cleaning</code>.</li><li><strong>Presentation (Route)</strong>: <code>tenderRoutes</code> sees <code>GET /tenders</code> and forwards to <code>TenderController.search</code>.</li><li><strong>Presentation (Controller)</strong>: <code>TenderController</code> extracts <code>q=cleaning</code> and calls the Use Case. <ul><li><em>Code</em>: <code>searchTenderUseCase.execute(&#39;cleaning&#39;)</code></li></ul></li><li><strong>Application (Use Case)</strong>: <code>SearchTenderUseCase</code> receives the command. <ul><li>It calls the repository contract: <code>tenderRepository.findByKeyword(&#39;cleaning&#39;)</code>.</li><li><em>Note</em>: The Use Case <strong>does not know</strong> we are using Turso/SQL. It just calls the interface.</li></ul></li><li><strong>Infrastructure (Repository)</strong>: The injected <code>TursoTenderRepository</code> runs the SQL: <ul><li><code>SELECT * FROM tenders WHERE description LIKE &#39;%cleaning%&#39;</code></li><li>It converts the SQL rows into <code>Tender</code> Entities and returns them.</li></ul></li><li><strong>Application</strong>: Receives the Entities and returns them to the Controller.</li><li><strong>Presentation</strong>: Converts the Entities to JSON and sends <code>200 OK</code> to the browser.</li></ol><h2 id="🧩-why-do-we-do-this-the-why" tabindex="-1">🧩 Why do we do this? (The &quot;Why&quot;) <a class="header-anchor" href="#🧩-why-do-we-do-this-the-why" aria-label="Permalink to &quot;🧩 Why do we do this? (The &quot;Why&quot;)&quot;">​</a></h2><ul><li><strong>Swap Components</strong>: Want to change from Turso to PostgreSQL? Just write a <code>PostgresTenderRepository</code> and swap it in <code>infrastructure</code>. The Domain and Application layers <strong>never change</strong>.</li><li><strong>Easy Testing</strong>: Use Cases can be tested without a database! We just pass a &quot;Mock Repository&quot; that returns fake data.</li><li><strong>Clarity</strong>: You know exactly where code belongs. Business rule? Domain. SQL query? Infrastructure. HTTP Status Code? Presentation.</li></ul>',23)])])}const p=o(i,[["render",n]]);export{m as __pageData,p as default};
